package com.opensocket.aievent.core.action.executor.issue.scoped;
import com.opensocket.aievent.core.integration.identity.*; import java.net.URLEncoder; import java.util.*; import tools.jackson.databind.ObjectMapper;
final class RedminePermissionProbeAdapter {
 private final ScopedProviderHttpSupport http; RedminePermissionProbeAdapter(ObjectMapper json){http=new ScopedProviderHttpSupport(json);}
 PermissionProbeObservation probe(IntegrationConnection c,IntegrationPrincipal p,IntegrationCredentialMetadata credential,IntegrationProjectMapping mapping,String secret){var caps=blank();var elevated=new LinkedHashSet<String>();var summary=new ArrayList<String>();try{var headers=new LinkedHashMap<>(http.redmineAuthHeaders(p,credential,secret));var me=http.get(ScopedProviderHttpSupport.join(c.baseUrl(),"/users/current.json"),headers,c.timeoutMs());if(me.statusCode()==401||me.statusCode()==403){denyAll(caps);return new PermissionProbeObservation(caps,List.of(),"Redmine authentication was rejected with "+me.statusCode()+".");}caps.put(IntegrationPermissionCapability.AUTHENTICATE,ScopedProviderHttpSupport.ok(me.statusCode())?PermissionProbeResultStatus.GRANTED:PermissionProbeResultStatus.ERROR);var meJson=http.parse(me.body());Object user=meJson.get("user");if(user instanceof Map<?,?> u&&Boolean.TRUE.equals(u.get("admin")))elevated.add("PROVIDER_ADMINISTRATOR");elevated.addAll(ScopedProviderHttpSupport.headerSet(me,"X-OpenDispatch-Elevated-Permissions"));if(mapping==null){summary.add("Authentication was probed without a Project Mapping.");return new PermissionProbeObservation(caps,List.copyOf(elevated),String.join(" ",summary));}String project=mapping.externalProjectId();var projectResponse=http.get(ScopedProviderHttpSupport.join(c.baseUrl(),"/projects/"+URLEncoder.encode(project,java.nio.charset.StandardCharsets.UTF_8)+".json"),headers,c.timeoutMs());boolean visible=ScopedProviderHttpSupport.ok(projectResponse.statusCode());caps.put(IntegrationPermissionCapability.PROJECT_VISIBLE,visible?PermissionProbeResultStatus.GRANTED:PermissionProbeResultStatus.DENIED);var issueResponse=http.get(ScopedProviderHttpSupport.join(c.baseUrl(),"/issues.json?project_id="+URLEncoder.encode(project,java.nio.charset.StandardCharsets.UTF_8)+"&limit=1"),headers,c.timeoutMs());caps.put(IntegrationPermissionCapability.READ_ISSUE,ScopedProviderHttpSupport.ok(issueResponse.statusCode())?PermissionProbeResultStatus.GRANTED:PermissionProbeResultStatus.DENIED);applyDeclaredCapabilities(caps,ScopedProviderHttpSupport.headerSet(projectResponse,"X-OpenDispatch-Capabilities"));applyDeclaredCapabilities(caps,ScopedProviderHttpSupport.headerSet(issueResponse,"X-OpenDispatch-Capabilities"));summary.add("Redmine Project visibility and read access were probed using the scoped Principal.");summary.add("Write capabilities remain NOT_TESTED unless the provider exposes explicit capability evidence.");return new PermissionProbeObservation(caps,List.copyOf(elevated),String.join(" ",summary));}catch(Exception e){caps.replaceAll((k,v)->v==PermissionProbeResultStatus.NOT_TESTED?PermissionProbeResultStatus.ERROR:v);return new PermissionProbeObservation(caps,List.copyOf(elevated),"Redmine Permission Probe failed: "+e.getClass().getSimpleName());}}
 private EnumMap<IntegrationPermissionCapability,PermissionProbeResultStatus> blank(){var m=new EnumMap<IntegrationPermissionCapability,PermissionProbeResultStatus>(IntegrationPermissionCapability.class);for(var c:IntegrationPermissionCapability.values())m.put(c,PermissionProbeResultStatus.NOT_TESTED);return m;} private void denyAll(Map<IntegrationPermissionCapability,PermissionProbeResultStatus> m){m.replaceAll((k,v)->PermissionProbeResultStatus.DENIED);} private void applyDeclaredCapabilities(Map<IntegrationPermissionCapability,PermissionProbeResultStatus> m,Set<String> values){for(String value:values){try{m.put(IntegrationPermissionCapability.valueOf(value),PermissionProbeResultStatus.GRANTED);}catch(Exception ignored){}}}
}
